const fresh=()=>({catalogVersion:CATALOG_VERSION,clients:[],projects:[],invoices:[],transactions:[],services:catalog.map(x=>({...x,id:id()})),settings:{business:'RAPS Creative',email:'rapscreativeindonesia@gmail.com',contact:'',payment:'',tnc:defaultTnc}});
function migrateCatalog(d){
 if((d.catalogVersion||0)>=CATALOG_VERSION)return null;
 const n=structuredClone(d),used=new Set(),aliases={'Catalog Website':'Business Catalog','UGC Production':'UGC Video','Cafe Visit':'Cafe Visit Content','Short-form Editing':'Short-Form Editing'};
 const normalize=x=>String(x||'').toLowerCase().trim();
 const untouched=x=>seed.some(z=>x.category===z[0]&&x.name===z[1]&&Number(x.price)===z[2]&&x.unit===z[3]&&x.sow===z[4]&&x.tnc===defaultTnc&&x.note==='Referensi awal; verifikasi harga dan ketentuan sebelum digunakan.');
 n.services=n.services.flatMap(x=>{
  if(!untouched(x))return [x];
  const hit=catalog.find(z=>z.catalogId.startsWith('p')&&normalize(z.name)===normalize(aliases[x.name]||x.name)&&!used.has(z.catalogId));
  if(hit){used.add(hit.catalogId);return [{...hit,id:x.id}]}
  if(n.projects.some(p=>p.service===x.id))return [{...x,note:'Arsip referensi lama; dipertahankan untuk proyek sebelumnya.'}];
  return [];
 });
 for(const x of catalog)if(!used.has(x.catalogId)&&!n.services.some(y=>y.catalogId===x.catalogId))n.services.push({...x,id:id()});
 n.catalogVersion=CATALOG_VERSION;return n;
}
let data=null,key=null,salt=null,section='dashboard',editing=null,search='',filter='',period=date().slice(0,7),toastTimer, idleTimer, busy=false;
