const iconPaths={globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18M12 3c-5 5-5 13 0 18"/>',camera:'<rect x="3" y="6" width="18" height="15" rx="3"/><circle cx="12" cy="13" r="4"/><path d="m7 6 2-3h6l2 3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',heart:'<path d="M20.8 5.6a5.5 5.5 0 0 0-8 .2l-.8.9-.8-.9a5.5 5.5 0 0 0-8 7.5L12 22l8.8-8.7a5.5 5.5 0 0 0 0-7.7Z"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4M3 16h4M17 8h4M17 16h4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',pen:'<path d="m4 16 12-12 4 4L8 20l-5 1zM13 7l4 4"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',trend:'<path d="M3 19h18M4 15l6-6 4 4 6-8M15 5h5v5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 7 9-7"/>',layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>'};
function colorIndex(d){const i=DIVISIONS.indexOf(d);return i>=0&&i<12?i:0}
function divIcon(d){return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+iconPaths[divisionIcons[colorIndex(d)]]+'</svg>'}
function noPrice(v){return String(v??'').replace(/(?:Rp\.?\s*|IDR\s*)(?:\d[\d.,]*)(?:\s*(?:juta|ribu|miliar|jt|rb|k))?/gi,'[sesuai penawaran]').replace(/(?:\s*\/\s*)?\[sesuai penawaran\](?:\s*per bulan)?/gi,'').replace(/\s*\/\s*$/,'').trim()}
function clientTerms(x){const raw=x.termsCustom!==undefined?x.termsCustom:specialTerms(x);const text=String(raw||'').replace(/[^.!?\n]*(?:Rp\.?\s*\d|IDR\s*\d)[^\n]*?(?=\.(?:\s+[A-Z]|$)|\n|$)/gi,m=>m.includes('fee')?' Ketentuan fee mengikuti penawaran.':'');return noPrice(text).replace(/\b(?:harga|biaya|fee)\s*:\s*(?=[.;]|$)/gi,'').trim()||'Ketentuan biaya dan jadwal mengikuti penawaran yang disepakati.'}
function presentationHome(){return '<section class="present-hero"><span class="eyebrow">RAPS CREATIVE</span><h1>Layanan kreatif.</h1><p>Pilih layanan untuk melihat cakupan pekerjaan dan ketentuannya.</p></section><div class="present-grid">'+DIVISIONS.slice(0,12).map((d,i)=>'<button class="present-tile tone-'+i+'" data-division="'+i+'"><span class="tile-icon">'+divIcon(d)+'</span><h2>'+esc(divisionLabels[i])+'</h2><p>'+esc(divisionDescriptions[i])+'</p><span class="tile-link">Lihat layanan <span aria-hidden="true">↗</span></span></button>').join('')+'</div>'}
function presentationDivision(){const i=colorIndex(division);return '<section class="present-hero division-hero tone-'+i+'"><span class="tile-icon">'+divIcon(division)+'</span><h1>'+esc(divisionLabels[i])+'</h1><p>'+esc(divisionDescriptions[i])+'</p></section>'+divisionCatalog()}
function togglePrivate(){if(!data||busy)return;privateMode=!privateMode;section='dashboard';search='';filter='';render();window.scrollTo(0,0)}

function serviceDiv(x){if(!x)return UNALLOC;const c=x.category||'';if(DIVISIONS.includes(c))return c;const m={'Add-on · Website Promo':'Website','Add-on · Website Reguler':'Website','Add-on · UGC Video':'UGC & Cafe Visit','Add-on · Cafe Visit':'UGC & Cafe Visit','Add-on · Editing':'Editing','Add-on · Scriptwriting':'Content & Scriptwriting','Add-on · Planning & Calendar':'Content & Scriptwriting','Add-on · Undangan Digital':'Undangan Digital','Social Media':'Social Media Management','UGC':'UGC & Cafe Visit'};if(c==='Add-on · Creator Support')return /WCC|foto tambahan|same-day|story takeover/i.test(x.name)?'Wedding Content Creator':'PA Creator';return m[c]||UNALLOC}
function validDiv(v){return DIVISIONS.includes(v)?v:UNALLOC}
function recordDiv(t,x){if(t==='services')return serviceDiv(x);if(t==='projects')return x.division?validDiv(x.division):serviceDiv(data.services.find(z=>z.id===x.service));if(t==='invoices'){const p=data.projects.find(z=>z.id===x.project);return p?recordDiv('projects',p):validDiv(x.division)}if(t==='transactions'){const i=data.invoices.find(z=>z.id===x.invoice);if(i)return recordDiv('invoices',i);const p=data.projects.find(z=>z.id===x.project);return p?recordDiv('projects',p):validDiv(x.division)}return validDiv(x.division)}
function clientDivs(x){const set=new Set((Array.isArray(x.divisions)?x.divisions:[]).filter(d=>DIVISIONS.includes(d)));for(const t of ['projects','invoices','transactions'])for(const z of data[t])if(z.client===x.id)set.add(recordDiv(t,z));if(!set.size)set.add(UNALLOC);return set}
function scoped(t,d=division){if(!d)return data[t];return data[t].filter(x=>t==='clients'?clientDivs(x).has(d):recordDiv(t,x)===d)}
function divisionCash(d,type,p){return sum(scoped('transactions',d).filter(t=>t.type===type&&(!p||t.date.startsWith(p))),t=>Number(t.amount))}
function divisionNav(){return '<div class="division-tabs">'+[['dashboard','Dashboard'],['clients','Klien'],['projects','Proyek'],['invoices','Invoice'],['transactions','Keuangan'],['reports','Laporan']].map(([k,n])=>'<button class="division-tab '+(section===k?'active':'')+'" data-go="'+k+'">'+n+'</button>').join('')+'</div>'}
function divisionOverview(){const m=date().slice(0,7),ps=scoped('projects'),iv=scoped('invoices'),ts=scoped('transactions');return head('DIVISI / RAPS OFFICE',division, 'Dashboard dan data khusus divisi ini.','Proyek baru','projects')+'<div class="metrics">'+metric('Pemasukan bulan ini',money(cash('Masuk',m)),'Pembayaran aktual')+metric('Pengeluaran bulan ini',money(cash('Keluar',m)),'Biaya aktual')+metric('Piutang',money(sum(iv,due)),'Sisa invoice')+metric('Klien / Proyek aktif',scoped('clients').length+' / '+ps.filter(p=>!['Selesai','Batal'].includes(p.status)).length,'Klien unik / proyek berjalan')+'</div><div class="quick-actions"><button class="outline" data-add="clients">+ Klien</button><button class="outline" data-add="invoices">+ Invoice</button><button class="outline" data-add="transactions">+ Transaksi</button></div><div class="split">'+panel('Arus kas / 6 bulan',chart(),link('reports','Lihat laporan'))+panel('Invoice belum lunas',iv.filter(i=>due(i)>0).slice(0,5).map(i=>row(i.number,clientName(i.client),esc(money(due(i))))).join('')||empty('Tidak ada tagihan terbuka.'),link('invoices','Semua invoice'))+'</div>'+divisionCatalog()+'<div class="split">'+panel('Proyek berjalan',ps.filter(p=>!['Selesai','Batal'].includes(p.status)).slice(0,6).map(p=>row(p.name,clientName(p.client)+' · '+fmt(p.deadline),pill(p.status))).join('')||empty(),link('projects','Semua proyek'))+panel('Transaksi terbaru',[...ts].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(t=>row(t.name,fmt(t.date),esc((t.type==='Keluar'?'-':'+')+money(t.amount)))).join('')||empty(),link('transactions','Semua transaksi'))+'</div>'}
function divisionSummary(){const m=date().slice(0,7);return panel('Rekap seluruh divisi','<div class="table-wrap"><table><thead><tr><th>Divisi</th><th>Klien*</th><th>Proyek aktif</th><th>Masuk bulan ini</th><th>Keluar bulan ini</th><th>Piutang</th></tr></thead><tbody>'+DIVISIONS.map((d,i)=>'<tr><td><button class="plain" data-division="'+i+'">'+esc(d)+'</button></td><td>'+scoped('clients',d).length+'</td><td>'+scoped('projects',d).filter(p=>!['Selesai','Batal'].includes(p.status)).length+'</td><td>'+esc(money(divisionCash(d,'Masuk',m)))+'</td><td>'+esc(money(divisionCash(d,'Keluar',m)))+'</td><td>'+esc(money(sum(scoped('invoices',d),due)))+'</td></tr>').join('')+'</tbody></table></div><p class="small muted">* Satu klien dapat terdaftar di beberapa divisi. Total klien utama dihitung unik; nilai transaksi dan invoice hanya dihitung sekali. Data yang belum memiliki divisi berada di Belum dialokasikan.</p>')}
