const b64=b=>btoa(Array.from(new Uint8Array(b),x=>String.fromCharCode(x)).join('')), un64=s=>Uint8Array.from(atob(s),x=>x.charCodeAt(0));
async function derive(p,s){return crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:600000,hash:'SHA-256'},await crypto.subtle.importKey('raw',enc.encode(p),'PBKDF2',false,['deriveKey']),{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function seal(d,k,s){const iv=crypto.getRandomValues(new Uint8Array(12));return {version:1,salt:b64(s),iv:b64(iv),cipher:b64(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,enc.encode(JSON.stringify(d))))}}
async function decryptVault(v,k){if(v.version!==1||!v.salt||!v.iv||!v.cipher)throw Error('Format cadangan tidak valid.');const s=un64(v.salt),d=JSON.parse(dec.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(v.iv)},k,un64(v.cipher))));if(!['clients','projects','invoices','transactions','services'].every(t=>Array.isArray(d[t]))||!d.settings)throw Error('Data tidak valid.');return {d,k,s}}
async function openVault(v,p){if(v.version!==1||!v.salt||!v.iv||!v.cipher)throw Error('Format cadangan tidak valid.');return decryptVault(v,await derive(p,un64(v.salt)))}
const SESSION_STORE='raps.studio.session.v1', IDLE_MS=15*60*1000, KEY_DB='raps-studio-session-keys';
let sessionToken='',sessionUntil=0,lastKeyWrite=0,sessionDb=null;
function sessionInfo(){try{return JSON.parse(sessionStorage.getItem(SESSION_STORE)||'null')}catch{return null}}
function sessionMeta(){if(!sessionToken)return;try{sessionStorage.setItem(SESSION_STORE,JSON.stringify({token:sessionToken,until:sessionUntil,section,division,privateMode}))}catch{}}
function keyDb(){if(!sessionDb)sessionDb=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Session storage unavailable'));return}const q=indexedDB.open(KEY_DB,1);q.onupgradeneeded=()=>q.result.createObjectStore('keys',{keyPath:'token'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('Session storage blocked'))});return sessionDb}
async function keyOp(mode,fn){const db=await keyDb();return new Promise((resolve,reject)=>{const tx=db.transaction('keys',mode),req=fn(tx.objectStore('keys'));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Session transaction aborted'))})}
async function pruneKeys(){const db=await keyDb();return new Promise((resolve,reject)=>{const tx=db.transaction('keys','readwrite'),q=tx.objectStore('keys').openCursor();q.onsuccess=()=>{const c=q.result;if(c){if(c.value.until<=Date.now())c.delete();c.continue()}};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function saveSessionKey(){if(!sessionToken||!key||!salt)return;const token=sessionToken,k=key,encodedSalt=b64(salt),until=sessionUntil+30000;await keyOp('readwrite',store=>store.put({token,key:k,salt:encodedSalt,until}));if(sessionToken!==token){await keyOp('readwrite',store=>store.delete(token));return}lastKeyWrite=Date.now()}
async function startSession(){sessionToken=id();sessionUntil=Date.now()+IDLE_MS;lastKeyWrite=0;try{await pruneKeys();await saveSessionKey();sessionMeta()}catch{endSession()}}
function endSession(){const token=sessionToken||sessionInfo()?.token;sessionToken='';sessionUntil=0;lastKeyWrite=0;try{sessionStorage.removeItem(SESSION_STORE)}catch{}if(token)keyOp('readwrite',store=>store.delete(token)).catch(()=>{})}
async function resumeSession(){const meta=sessionInfo();if(!meta||typeof meta.token!=='string'||!Number.isFinite(meta.until)||meta.until<=Date.now())return false;const raw=localStorage.getItem(STORE);if(!raw)return false;const v=JSON.parse(raw),rec=await keyOp('readonly',store=>store.get(meta.token));if(!rec||rec.until<=Date.now()||rec.salt!==v.salt||!rec.key||rec.key.extractable!==false)return false;const o=await decryptVault(v,rec.key);if(meta.until<=Date.now())return false;data=o.d;key=o.k;salt=o.s;sessionToken=meta.token;sessionUntil=meta.until;lastKeyWrite=0;const upgraded=migrateCatalog(data);if(upgraded)await persist(upgraded);unlock(meta);return true}
function checkSessionExpiry(){if(data&&sessionUntil&&Date.now()>=sessionUntil&&!busy)gate()}
async function boot(){const meta=sessionInfo();if(!meta){gate();return}$('#gate').hidden=true;$('#app').hidden=true;busy=true;try{if(!await resumeSession())gate()}catch{gate()}finally{busy=false}}

async function persist(next){const v=await seal(next,key,salt);localStorage.setItem(STORE,JSON.stringify(v));data=next}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function gate(){privateMode=false;endSession();clearTimeout(idleTimer);data=null;key=null;salt=null;$('#app').hidden=true;$('#gate').hidden=false;$('#view').innerHTML='';$('#fields').innerHTML='';$('#print-area').innerHTML='';if($('#editor').open)$('#editor').close();editing=null;search='';filter='';$('#password').value='';$('#confirm').value='';$('#gate-error').textContent='';const exists=!!localStorage.getItem(STORE);$('#gate-title').innerHTML=exists?'Selamat datang<br>kembali.':'Ruang kerja<br>pribadi.';$('#gate-desc').textContent=exists?'Masukkan kata sandi vault untuk membuka data di perangkat ini.':'Buat kata sandi minimal 10 karakter untuk mengenkripsi data di browser ini.';$('#confirm-wrap').hidden=exists;$('#confirm').required=!exists;$('#gate-button').textContent=exists?'Buka ruang kerja':'Buat ruang kerja';$('#password').autocomplete=exists?'current-password':'new-password'}
function unlock(meta=null){privateMode=meta?.privateMode===true;division=meta&&DIVISIONS.includes(meta.division)?meta.division:'';section=meta&&nav.some(x=>x[0]===meta.section)?meta.section:'dashboard';search='';filter='';$('#gate').hidden=true;$('#app').hidden=false;$('#password').value='';$('#confirm').value='';$('#today').textContent=fmt(date());render();resetIdle()}
function resetIdle(){if(!data)return;const now=Date.now();if(sessionUntil&&now>=sessionUntil&&!busy){gate();return}sessionUntil=now+IDLE_MS;sessionMeta();if(sessionToken&&now-lastKeyWrite>=30000){lastKeyWrite=now;saveSessionKey().catch(()=>{})}clearTimeout(idleTimer);idleTimer=setTimeout(()=>{if(!busy)gate();else{idleTimer=setTimeout(checkSessionExpiry,1000)}},IDLE_MS)}
$('#gate-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('#gate-button').disabled=true;$('#gate-error').textContent='';try{const p=$('#password').value,raw=localStorage.getItem(STORE);if(raw){const o=await openVault(JSON.parse(raw),p);data=o.d;key=o.k;salt=o.s;const upgraded=migrateCatalog(data);if(upgraded)await persist(upgraded)}else{if(p!==$('#confirm').value)throw Error('Kata sandi tidak sama.');salt=crypto.getRandomValues(new Uint8Array(16));key=await derive(p,salt);await persist(fresh())}await startSession();unlock()}catch(e){$('#gate-error').textContent=e.name==='OperationError'?'Kata sandi salah atau data rusak.':e.message}finally{busy=false;$('#gate-button').disabled=false}};
['pointerdown','keydown','touchstart'].forEach(e=>document.addEventListener(e,resetIdle,{passive:true,capture:true}));document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkSessionExpiry()});window.addEventListener('pageshow',checkSessionExpiry);
