function head(label,title,sub,action='',target=''){return '<div class="page-head"><div><div class="eyebrow">'+esc(label)+'</div><h1>'+esc(title)+'</h1><p>'+esc(sub)+'</p></div>'+(action?'<button class="primary" data-add="'+target+'">+ '+esc(action)+'</button>':'')+'</div>'}
const clientName=i=>data.clients.find(x=>x.id===i)?.name||'—',projectName=i=>data.projects.find(x=>x.id===i)?.name||'—',serviceName=i=>data.services.find(x=>x.id===i)?.name||'—',invoiceName=i=>data.invoices.find(x=>x.id===i)?.number||'—';
const total=i=>Math.max(0,Number(i.qty)*Number(i.price)-Number(i.discount||0)),paid=i=>data.transactions.filter(t=>t.invoice===i.id&&t.type==='Masuk').reduce((a,t)=>a+Number(t.amount),0),due=i=>Math.max(0,total(i)-paid(i)), invStatus=i=>due(i)===0?'Lunas':paid(i)>0?'Sebagian':i.due&&i.due<date()?'Jatuh tempo':'Belum dibayar';
const sum=(arr,fn)=>arr.reduce((a,b)=>a+fn(b),0),cash=(type,p)=>divisionCash(division,type,p);
const pill=s=>'<span class="pill '+(['Lunas','Selesai','Aktif','Masuk'].includes(s)?'good':['Jatuh tempo','Keluar','Sebagian'].includes(s)?'warn':'')+'">'+esc(s)+'</span>';
function metric(label,value,note){return '<div class="metric"><div class="eyebrow">'+esc(label)+'</div><div class="number">'+esc(value)+'</div><small>'+esc(note)+'</small></div>'}
function row(a,b,c){return '<div class="listrow"><div><strong>'+esc(a)+'</strong><small>'+esc(b)+'</small></div><div>'+c+'</div></div>'}
function empty(s='Belum ada data.'){return '<div class="empty">'+esc(s)+'</div>'}
function panel(title,body,extra=''){return '<article class="panel"><div class="panel-head"><h2>'+esc(title)+'</h2>'+extra+'</div>'+body+'</article>'}
function link(s,label){return '<button class="plain" data-go="'+s+'">'+esc(label)+'</button>'}
function months(){const d=new Date(date()+'T12:00:00');return Array.from({length:6},(_,i)=>{let x=new Date(d.getFullYear(),d.getMonth()-5+i,1);return [x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0'),x.toLocaleDateString('id-ID',{month:'short'})]})}
function chart(){const a=months().map(([m,l])=>[l,cash('Masuk',m),cash('Keluar',m)]),max=Math.max(1,...a.flatMap(x=>x.slice(1)));return '<div class="chart">'+a.map(([l,i,o])=>'<div class="bar-row"><span>'+esc(l)+'</span><div class="bar-pair"><div class="bar" title="'+esc(money(i))+'" style="width:'+i/max*100+'%"></div><div class="bar out" title="'+esc(money(o))+'" style="width:'+o/max*100+'%"></div></div></div>').join('')+'</div><p class="small muted">Plum: pemasukan · Beige: pengeluaran</p>'}
function dashboard(){if(!privateMode)return division?presentationDivision():presentationHome();if(division)return divisionOverview();const m=date().slice(0,7);return head('01 / PRIVATE STUDIO','Studio overview.','Catatan bisnis, satu ruang kerja pribadi.','Klien baru','clients')+'<div class="metrics">'+metric('Pemasukan bulan ini',money(cash('Masuk',m)),'Pembayaran diterima')+metric('Pengeluaran bulan ini',money(cash('Keluar',m)),'Biaya tercatat')+metric('Piutang',money(sum(data.invoices,due)),'Sisa seluruh invoice')+metric('Klien / Proyek aktif',data.clients.length+' / '+data.projects.filter(p=>!['Selesai','Batal'].includes(p.status)).length,'Total klien / proyek berjalan')+'</div><div class="split">'+panel('Arus kas / 6 bulan',chart(),link('reports','Lihat laporan'))+panel('Invoice belum lunas',data.invoices.filter(i=>due(i)>0).slice(0,5).map(i=>row(i.number,clientName(i.client),esc(money(due(i))))).join('')||empty('Tidak ada tagihan terbuka.'),link('invoices','Semua invoice'))+'</div><div class="split">'+panel('Proyek berjalan',data.projects.filter(p=>!['Selesai','Batal'].includes(p.status)).slice(0,6).map(p=>row(p.name,clientName(p.client)+' · '+fmt(p.deadline),pill(p.status))).join('')||empty(),link('projects','Semua proyek'))+panel('Transaksi terbaru',[...data.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(t=>row(t.name,fmt(t.date),esc((t.type==='Keluar'?'-':'+')+money(t.amount)))).join('')||empty(),link('transactions','Semua transaksi'))+'</div>'+divisionSummary()}
const configs={
clients:{title:'Klien',singular:'klien',sub:'Database brand, kontak, dan histori kerja sama.',columns:['Nama / Brand','Kontak','Status','Nilai invoice','Aksi'],fields:[['name','Nama brand / klien','text',1],['pic','Nama PIC','text'],['phone','WhatsApp','tel'],['email','Email','email'],['industry','Kategori bisnis','text'],['source','Sumber klien','text'],['status','Status','select',0,['Prospek','Aktif','Selesai','Tidak aktif']],['notes','Catatan','textarea']]},
projects:{title:'Proyek',singular:'proyek',sub:'Kelola brief, deadline, scope, dan progress pekerjaan.',columns:['Proyek','Klien','Deadline','Nilai','Status','Aksi'],fields:[['name','Nama proyek','text',1],['client','Klien','relation',1,'clients'],['service','Layanan','relation',0,'services'],['value','Nilai kesepakatan (Rp)','number'],['start','Tanggal mulai','date'],['deadline','Deadline','date'],['status','Status','select',0,['Brief','Produksi','Review','Revisi','Selesai','Batal']],['sow','Scope of Work','textarea'],['tnc','T&C / Kesepakatan','textarea'],['notes','Catatan / link file','textarea']]},
invoices:{title:'Invoice',singular:'invoice',sub:'Tagihan, pembayaran parsial dan sisa pembayaran.',columns:['Nomor invoice','Klien','Jatuh tempo','Total','Terbayar','Sisa','Status','Aksi'],fields:[['number','Nomor invoice','text',1],['client','Klien','relation',1,'clients'],['project','Proyek','relation',0,'projects'],['name','Deskripsi pekerjaan','text',1],['date','Tanggal terbit','date',1],['due','Jatuh tempo','date'],['qty','Jumlah','number',1],['price','Harga satuan (Rp)','number',1],['discount','Diskon (Rp)','number'],['notes','Catatan invoice','textarea']]},
transactions:{title:'Keuangan',singular:'transaksi',sub:'Rekap pemasukan dan pengeluaran aktual. Pembayaran invoice tercatat satu kali di sini.',columns:['Tanggal','Keterangan','Kategori','Klien / Invoice','Jenis','Nominal','Aksi'],fields:[['date','Tanggal','date',1],['name','Keterangan','text',1],['type','Jenis','select',1,['Masuk','Keluar']],['amount','Nominal (Rp)','number',1],['category','Kategori','select',0,['Pembayaran klien','Operasional','Freelancer','Transportasi','Peralatan','Iklan','Lainnya']],['client','Klien (opsional)','relation',0,'clients'],['invoice','Invoice (khusus pemasukan)','relation',0,'invoices'],['method','Metode pembayaran','select',0,['Transfer','Tunai','QRIS','Lainnya']],['notes','Catatan','textarea']]},
services:{title:'Layanan',singular:'layanan',sub:'Paket, harga, SOW dan T&C dalam satu tempat.',fields:[['category','Kategori','text',1],['name','Nama layanan','text',1],['price','Harga referensi (Rp, 0 = custom)','number'],['unit','Satuan / Durasi','text'],['sow','Scope of Work','textarea'],['tnc','T&C layanan (termasuk aturan tambahan)','textarea'],['note','Catatan / add-on','textarea']]}
};
function actions(t,x){return '<div class="actions">'+(t==='invoices'?'<button class="plain" data-print="'+x.id+'">Cetak</button>'+(due(x)>0?'<button class="plain" data-pay="'+x.id+'">Bayar</button>':''):'')+'<button class="plain" data-edit="'+t+':'+x.id+'">Edit</button><button class="plain danger" data-delete="'+t+':'+x.id+'">Hapus</button></div>'}
function cells(t,x){let a=[];if(t==='clients')a=[esc(x.name)+'<small>'+esc(x.industry)+'</small>',esc(x.pic||x.phone||'—')+'<small>'+esc(x.phone||x.email||'')+'</small>',pill(x.status),esc(money(sum(scoped('invoices').filter(i=>i.client===x.id),total)))];if(t==='projects')a=[esc(x.name)+'<small>'+esc(serviceName(x.service))+'</small>',esc(clientName(x.client)),esc(fmt(x.deadline)),esc(money(x.value)),pill(x.status)];if(t==='invoices')a=[esc(x.number)+'<small>'+esc(x.name)+'</small>',esc(clientName(x.client)),esc(fmt(x.due)),esc(money(total(x))),esc(money(paid(x))),esc(money(due(x))),pill(invStatus(x))];if(t==='transactions')a=[esc(fmt(x.date)),esc(x.name),esc(x.category),esc(clientName(x.client))+'<small>'+esc(invoiceName(x.invoice))+'</small>',pill(x.type),esc(money(x.amount))];if(!division&&t==='clients')a.splice(1,0,esc([...clientDivs(x)].join(' · ')));if(!division&&['projects','invoices','transactions'].includes(t))a.splice(1,0,esc(recordDiv(t,x)));return [...a,actions(t,x)].map(s=>'<td>'+s+'</td>').join('')}
function matching(t){return scoped(t).filter(x=>{const status=t==='invoices'?invStatus(x):x.status||x.type||x.category;return (!filter||status===filter)&&(!search||[...Object.values(x),clientName(x.client),projectName(x.project),invoiceName(x.invoice)].join(' ').toLowerCase().includes(search.toLowerCase()))})}
function table(t){const a=matching(t);return a.length?'<div class="table-wrap"><table><thead><tr>'+(division?configs[t].columns:[configs[t].columns[0],'Divisi',...configs[t].columns.slice(1)]).map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+a.map(x=>'<tr>'+cells(t,x)+'</tr>').join('')+'</tbody></table></div>':empty('Belum ada catatan yang cocok.')}
function serviceCards(items){return items.map(x=>{const tone=colorIndex(serviceDiv(x));const unit=noPrice(x.unit);return '<article class="service simple-service tone-'+tone+'"><div class="service-top"><span class="service-mark">'+divIcon(serviceDiv(x))+'</span><div><h2>'+esc(noPrice(x.name))+'</h2>'+(unit?'<p class="muted small">'+esc(unit)+'</p>':'')+'</div></div><details class="service-detail"><summary>Detail layanan</summary><div class="service-content"><h3>Scope of Work</h3><div class="rule-text">'+esc(noPrice(x.sow||'Belum ditentukan'))+'</div><h3>Terms & Conditions</h3><div class="rule-text">'+esc(privateMode?noPrice(contractTerms(x)):clientTerms(x))+'</div></div></details>'+(privateMode?'<div class="service-edit"><button class="plain" data-edit="services:'+esc(x.id)+'">Edit</button></div>':'')+'</article>'}).join('')||empty()}
function services(){return serviceCards(matching('services'))}
function divisionCatalog(){const items=scoped('services'),packages=items.filter(x=>!String(x.category).startsWith('Add-on')),addons=items.filter(x=>String(x.category).startsWith('Add-on'));return '<section class="division-catalog" id="division-catalog"><div class="catalog-heading"><h2>Pilihan layanan</h2>'+(privateMode?'<button class="mini-action" data-add="services">+ Tambah</button>':'')+'</div><div class="catalog-grid">'+serviceCards(packages)+'</div>'+(addons.length?'<details class="addon-disclosure"><summary>Layanan tambahan <span>'+addons.length+'</span></summary><div class="catalog-grid">'+serviceCards(addons)+'</div></details>':'')+'</section>'}
function listing(t){const c=configs[t],opts=[...new Set(scoped(t).map(x=>t==='invoices'?invStatus(x):x.status||x.type||x.category).filter(Boolean))];return head('PRIVATE RECORDS',c.title,c.sub,'Tambah '+c.singular,t)+'<div class="toolbar"><input id="search" type="search" placeholder="Cari '+esc(c.singular)+'..." value="'+esc(search)+'"><select id="filter"><option value="">Semua '+(t==='services'?'kategori':'status')+'</option>'+opts.map(o=>'<option '+(filter===o?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select></div><div id="results" class="'+(t==='services'?'catalog-grid':'panel')+'">'+(t==='services'?services():table(t))+'</div>'}
function reports(){const ins=cash('Masuk',period),outs=cash('Keluar',period),a=scoped('transactions').filter(t=>t.date.startsWith(period));return head('FINANCIAL REVIEW','Laporan.','Rekap arus kas berdasarkan bulan transaksi.')+'<div class="toolbar"><label>Bulan<input type="month" id="period" value="'+esc(period)+'"></label><button class="outline" id="csv">Ekspor CSV bulan ini</button></div><div class="metrics">'+metric('Pemasukan',money(ins),'Aktual')+metric('Pengeluaran',money(outs),'Aktual')+metric('Arus kas bersih',money(ins-outs),'Bukan laba akuntansi')+metric('Transaksi',a.length,'Bulan terpilih')+'</div>'+panel('Rincian transaksi',a.length?a.map(t=>row(t.name,fmt(t.date)+' · '+t.category,esc((t.type==='Keluar'?'-':'+')+money(t.amount)))).join(''):empty())+panel('Tren 6 bulan',chart())}
function settings(){return head('PRIVATE WORKSPACE','Pengaturan.','Identitas bisnis, keamanan dan cadangan data.')+panel('Identitas & ketentuan','<p>'+esc(data.settings.business)+'<br>'+esc(data.settings.email)+'</p><p class="muted small">'+esc(data.settings.tnc)+'</p><button class="outline" data-add="settings">Edit identitas & T&C</button>')+panel('Penyimpanan & keamanan','<div class="setting-row"><div><strong>Vault terenkripsi</strong><p>Data disimpan di browser ini, dengan AES-GCM. Tidak tersinkron antar perangkat.</p></div><button class="outline" id="lock-settings">Kunci</button></div><div class="setting-row"><div><strong>Unduh cadangan</strong><p>File terenkripsi, memerlukan kata sandi yang sama.</p></div><button class="outline" id="backup-settings">Unduh</button></div><div class="setting-row"><div><strong>Pulihkan cadangan</strong><p>Mengganti vault lokal setelah kata sandi cadangan diverifikasi.</p></div><button class="outline" id="restore-settings">Pulihkan</button></div><p class="small muted">Menghapus data browser atau kehilangan kata sandi dapat menyebabkan kehilangan data. CSV dan hasil cetak tidak terenkripsi.</p>')}
function render(){if(!data)return;if(!privateMode)section='dashboard';sessionMeta();$('#app').classList.toggle('presentation-mode',!privateMode);$('#mode-toggle').textContent=privateMode?'Presentasi':'Internal';$('#mode-toggle').setAttribute('aria-pressed',String(privateMode));$('#backup-top').hidden=!privateMode;$('#today').hidden=!privateMode;const navScroll=$('#nav').scrollTop,navLeft=$('#nav').scrollLeft;const main=(privateMode?nav:nav.filter(x=>x[0]==='dashboard')).map(([k,n,p])=>'<button class="nav-btn '+(!division&&k===section?'active':'')+'" data-global="'+k+'"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+p+'"/></svg>'+(k==='dashboard'?(privateMode?'Overview':'Beranda'):n)+'</button>').join('');$('#nav').innerHTML=main+'<div class="nav-label division-label">LAYANAN</div>'+DIVISIONS.filter(d=>privateMode||d!==UNALLOC).map(d=>{const i=DIVISIONS.indexOf(d);return '<button class="nav-btn division-link tone-'+colorIndex(d)+' '+(division===d?'active':'')+'" data-division="'+i+'"><span class="division-dot"></span>'+esc(divisionLabels[i]||d)+'</button>'}).join('');$('#nav').scrollTop=navScroll;$('#nav').scrollLeft=navLeft;$('#crumb').textContent=division?(divisionLabels[DIVISIONS.indexOf(division)]||division)+(privateMode?' / '+(nav.find(x=>x[0]===section)?.[1]||'Overview'):''):(privateMode?(nav.find(x=>x[0]===section)?.[1]||'Overview'):'Beranda');$('#view').innerHTML=(division&&privateMode?divisionNav():'')+(section==='dashboard'?dashboard():section==='reports'?reports():section==='settings'?settings():listing(section))}

const defaults=t=>t==='clients'?{status:'Prospek'}:t==='projects'?{status:'Brief',start:date(),tnc:data.settings.tnc}:t==='invoices'?{number:'INV-'+date().replaceAll('-','')+'-'+id().slice(0,4).toUpperCase(),date:date(),qty:1,price:0,discount:0}:t==='transactions'?{date:date(),type:'Masuk',category:'Pembayaran klien'}:t==='services'?{price:0,tnc:data.settings.tnc}:{};
function field(f,x){const [k,label,type,req,opts]=f,v=x[k]??'',attrs='name="'+k+'" '+(req?'required ':'');let control='';if(type==='divisions'){control='<div class="division-checks">'+DIVISIONS.filter(d=>d!==UNALLOC).map(d=>'<label><input type="checkbox" name="divisions" value="'+esc(d)+'" '+((Array.isArray(v)?v:[]).includes(d)?'checked':'')+'>'+esc(d)+'</label>').join('')+'</div>'}else if(type==='textarea')control='<textarea '+attrs+'>'+esc(v)+'</textarea>';else if(type==='select'||type==='relation'){let choices=type==='relation'?(opts==='clients'?data.clients:division?scoped(opts).concat(data[opts].filter(z=>z.id===v&&!scoped(opts).some(y=>y.id===z.id))):data[opts]).map(z=>[z.id,opts==='services'?z.category+' / '+z.name+' — '+money(z.price):z.number||z.name]):opts.map(z=>[z,z]);control='<select '+attrs+'><option value="">Pilih...</option>'+choices.map(([a,b])=>'<option value="'+esc(a)+'" '+(String(v)===String(a)?'selected':'')+'>'+esc(b)+'</option>').join('')+'</select>'}else control='<input '+attrs+' type="'+type+'" '+(type==='number'?'min="0" step="1" ':'')+'value="'+esc(v)+'">';return type==='divisions'?'<div class="wide"><label>'+esc(label)+'</label>'+control+'</div>':'<label class="'+(type==='textarea'?'wide':'')+'">'+esc(label)+(req?' *':'')+control+'</label>'}
function edit(t,i,initial={}){if(!data)return;const base=t==='settings'?data.settings:i?data[t].find(x=>x.id===i):{...defaults(t),...initial};const x=base?{...base}:null;if(x&&['projects','invoices','transactions'].includes(t))x.division=i?recordDiv(t,x):(initial.division||division||UNALLOC);if(x&&t==='clients'&&!i)x.divisions=division&&division!==UNALLOC?[division]:[];if(x&&t==='services'&&!i&&division&&division!==UNALLOC)x.category=division;if(!x)return;editing={t,i};if(t==='services'){editing.originalTnc=x.tnc;editing.initialTerms=contractTerms(x);x.tnc=editing.initialTerms}let fs=t==='settings'?[['business','Nama bisnis','text',1],['email','Email','email'],['contact','Kontak','text'],['payment','Instruksi pembayaran','textarea'],['tnc','Draf T&C umum','textarea']]:configs[t].fields.slice();if(t==='clients')fs.push(['divisions','Divisi layanan (boleh lebih dari satu)','divisions']);if(['projects','invoices','transactions'].includes(t))fs.unshift(['division','Divisi layanan','select',1,DIVISIONS]);if(t==='transactions')fs.splice(fs.findIndex(z=>z[0]==='invoice'),0,['project','Proyek (opsional)','relation',0,'projects']);$('#edit-title').textContent=t==='settings'?'Identitas & T&C':(i?'Edit ':'Tambah ')+configs[t].singular;$('#fields').innerHTML=fs.map(f=>field(f,x)).join('')+(t==='services'&&i?'<div class="wide service-delete"><button type="button" class="plain danger" data-delete="services:'+esc(i)+'">Hapus layanan</button></div>':'');$('#edit-error').textContent='';$('#editor').showModal()}
$('#fields').addEventListener('change',e=>{if(!editing)return;const f=$('#edit-form').elements;if(editing.t==='projects'&&e.target.name==='service'){const s=data.services.find(x=>x.id===e.target.value);if(s){f.division.value=serviceDiv(s);if(!editing.i){f.value.value=s.price;f.sow.value=s.sow;f.tnc.value=contractTerms(s)}}}if(editing.t==='invoices'&&e.target.name==='project'){const p=data.projects.find(x=>x.id===e.target.value);if(p){f.division.value=recordDiv('projects',p);f.client.value=p.client;if(!editing.i){f.name.value=p.name;f.price.value=p.value}}}if(editing.t==='transactions'&&e.target.name==='project'){const p=data.projects.find(x=>x.id===e.target.value);if(p){f.division.value=recordDiv('projects',p);f.client.value=p.client}}if(editing.t==='transactions'&&e.target.name==='invoice'){const i=data.invoices.find(x=>x.id===e.target.value);if(i){f.client.value=i.client;f.type.value='Masuk';f.division.value=recordDiv('invoices',i);f.project.value=i.project||'';if(!editing.i){f.amount.value=due(i);f.name.value='Pembayaran '+i.number}}}});
$('#edit-form').onsubmit=async e=>{e.preventDefault();if(busy||!editing)return;busy=true;const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{const {t,i}=editing,fs=['settings','rules'].includes(t)?[]:configs[t].fields,x=Object.fromEntries(new FormData(e.target));if(t==='rules'){const n=structuredClone(data);n.rules={...(n.rules||{}),[i]:x.body};await persist(n);$('#editor').close();editing=null;render();toast('Aturan disimpan.');return;}if(t==='services'){if(x.tnc!==editing.initialTerms)x.termsCustom=x.tnc;x.tnc=editing.originalTnc||defaultTnc}for(const [k,l,ty] of fs)if(ty==='number')x[k]=Number(x[k]||0);if(t==='clients')x.divisions=new FormData(e.target).getAll('divisions');if(['projects','invoices','transactions'].includes(t))x.division=validDiv(x.division);if(t==='projects'&&x.service){const sv=data.services.find(z=>z.id===x.service);if(sv&&serviceDiv(sv)!==UNALLOC)x.division=serviceDiv(sv)}if(t==='invoices'&&x.project){const p=data.projects.find(z=>z.id===x.project);if(p)x.division=recordDiv('projects',p)}if(t==='transactions'&&x.project){const p=data.projects.find(z=>z.id===x.project);if(p){if(x.client&&x.client!==p.client)throw Error('Proyek dan klien tidak sesuai.');x.client=p.client;x.division=recordDiv('projects',p)}}const next=structuredClone(data);if(t==='invoices'){if(x.qty<1||x.discount>x.qty*x.price||!Number.isSafeInteger(x.qty*x.price))throw Error('Jumlah atau diskon tidak valid.');if(data.invoices.some(z=>z.id!==i&&z.number===x.number))throw Error('Nomor invoice sudah dipakai.');if(x.project&&data.projects.find(p=>p.id===x.project)?.client!==x.client)throw Error('Proyek dan klien tidak sesuai.');if(i){const old=data.invoices.find(z=>z.id===i);if(total(x)<paid(old))throw Error('Total tidak boleh lebih kecil dari pembayaran tercatat.');if(paid(old)>0&&old.client!==x.client)throw Error('Klien invoice yang sudah dibayar tidak dapat diubah.')}}if(t==='transactions'){if(x.amount<=0||!Number.isSafeInteger(x.amount))throw Error('Nominal harus lebih dari nol.');if(x.invoice){const inv=data.invoices.find(z=>z.id===x.invoice);if(!inv||x.type!=='Masuk'||x.client&&x.client!==inv.client)throw Error('Pembayaran invoice harus pemasukan untuk klien yang sesuai.');x.client=inv.client;x.division=recordDiv('invoices',inv);x.project=inv.project||'';const prior=data.transactions.find(z=>z.id===i&&z.invoice===x.invoice&&z.type==='Masuk');if(x.amount>due(inv)+Number(prior?.amount||0))throw Error('Pembayaran melebihi sisa invoice.')}}if(t==='settings')next.settings=x;else if(i)next[t]=next[t].map(z=>z.id===i?{...z,...x,id:i}:z);else next[t].unshift({...x,id:id()});await persist(next);$('#editor').close();editing=null;render();toast('Catatan disimpan.')}catch(e){$('#edit-error').textContent=e.message}finally{busy=false;btn.disabled=false}};
async function remove(t,i){if(busy)return;if(t==='clients'&&[...data.projects,...data.invoices,...data.transactions].some(x=>x.client===i)||t==='projects'&&[...data.invoices,...data.transactions].some(x=>x.project===i)||t==='invoices'&&data.transactions.some(x=>x.invoice===i)||t==='services'&&data.projects.some(x=>x.service===i)){toast('Tidak dapat dihapus karena masih terhubung ke catatan lain.');return}if(!confirm('Hapus catatan ini? Perubahan tidak dapat dibatalkan.'))return;busy=true;try{const n=structuredClone(data);n[t]=n[t].filter(x=>x.id!==i);await persist(n);if($('#editor').open&&editing?.t===t&&editing?.i===i){$('#editor').close();editing=null}render();toast('Catatan dihapus.')}catch(e){toast(e.message)}finally{busy=false}}
function download(name,content,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function backup(){const raw=localStorage.getItem(STORE);if(raw)download('raps-vault-'+date()+'.json',raw,'application/json')}
$('#restore-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f||busy)return;if(f.size>20*1024*1024){toast('Cadangan terlalu besar.');return}const p=prompt('Masukkan kata sandi cadangan:');if(p===null)return;busy=true;try{const raw=await f.text();await openVault(JSON.parse(raw),p);if(confirm('Ganti seluruh data lokal dengan cadangan ini?')){localStorage.setItem(STORE,raw);gate();toast('Cadangan dipulihkan. Buka dengan kata sandi cadangan.')}}catch(e){toast('Cadangan atau kata sandi tidak valid.')}finally{busy=false}};
function printInvoice(i){const x=data.invoices.find(z=>z.id===i);if(!x)return;const c=data.clients.find(z=>z.id===x.client);$('#print-area').innerHTML='<h1>INVOICE</h1><p><strong>'+esc(data.settings.business)+'</strong><br>'+esc(data.settings.email)+'<br>'+esc(data.settings.contact)+'</p><hr><p>'+esc(x.number)+' · '+esc(fmt(x.date))+'<br>Jatuh tempo: '+esc(fmt(x.due))+'</p><p>Ditagihkan kepada: <strong>'+esc(c?.name||'')+'</strong><br>'+esc(c?.email||'')+'</p><table><thead><tr><th>Deskripsi</th><th>Qty</th><th>Harga</th></tr></thead><tbody><tr><td>'+esc(x.name)+'</td><td>'+esc(x.qty)+'</td><td>'+esc(money(x.price))+'</td></tr></tbody></table><p>Diskon: '+esc(money(x.discount))+'<br>Total: '+esc(money(total(x)))+'<br>Terbayar: '+esc(money(paid(x)))+'</p><h2>Sisa: '+esc(money(due(x)))+'</h2><p>'+esc(data.settings.payment)+'<br>'+esc(x.notes)+'</p>';window.print()}
window.addEventListener('afterprint',()=>$('#print-area').innerHTML='');
function csv(){const clean=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const rows=[['Tanggal','Keterangan','Jenis','Kategori','Nominal','Klien','Invoice','Metode','Catatan'],...scoped('transactions').filter(t=>t.date.startsWith(period)).map(t=>[t.date,t.name,t.type,t.category,t.amount,clientName(t.client),invoiceName(t.invoice),t.method,t.notes])];download('raps-keuangan-'+(division?division.replace(/[^a-z0-9]+/gi,'-')+'-':'')+period+'.csv','\ufeff'+rows.map(r=>r.map(clean).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(b.id==='mode-toggle'){togglePrivate();return}if(!privateMode&&data&&(d.add||d.edit||d.delete||d.print||d.pay||d.rule||d.termsCopy||d.termsPrint))return;if(d.rule)editRule(d.rule);if(d.ruleCopy)copyTerms(d.ruleCopy==='general'?generalRules():divisionRules(d.ruleCopy));if(d.termsCopy){const x=data.services.find(z=>z.id===d.termsCopy);if(x)copyTerms(contractTerms(x))}if(d.termsPrint)printTerms(data.services.find(z=>z.id===d.termsPrint));if(d.global){division='';go(d.global)}if(d.division!==undefined)changeDivision(Number(d.division));if(d.go)go(d.go);if(d.add)edit(d.add);if(d.edit){const [t,i]=d.edit.split(':');edit(t,i)}if(d.delete){const [t,i]=d.delete.split(':');remove(t,i)}if(d.print)printInvoice(d.print);if(d.pay){const i=data.invoices.find(z=>z.id===d.pay);edit('transactions',null,{invoice:i.id,client:i.client,amount:due(i),name:'Pembayaran '+i.number})}if(['lock','lock-settings'].includes(b.id)&&!busy)gate();if(['backup-top','backup-settings'].includes(b.id))backup();if(['restore-gate','restore-settings'].includes(b.id))$('#restore-file').click();if(b.id==='csv')csv();if(['cancel-editor','close-editor'].includes(b.id)&&!busy){$('#editor').close();editing=null}});
$('#view').addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#results').innerHTML=section==='services'?services():table(section)}});$('#view').addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;$('#results').innerHTML=section==='services'?services():table(section)}if(e.target.id==='period'&&e.target.value){period=e.target.value;render()}});
boot();
